import{_ as e,o as n,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"研究型 Agent","description":"设计研究型 Agent 的问题界定、检索计划、来源选择、证据笔记、交叉核验、引用综合、停止条件与质量评测。","frontmatter":{"title":"研究型 Agent","description":"设计研究型 Agent 的问题界定、检索计划、来源选择、证据笔记、交叉核验、引用综合、停止条件与质量评测。","verified_at":"2026-07-31","source":["https://www.w3.org/TR/prov-overview/","https://www.crossref.org/documentation/retrieve-metadata/rest-api/","https://www.rfc-editor.org/rfc/rfc9110","https://docs.langchain.com/oss/python/langchain/multi-agent"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/domain-agent-architectures/research-agent.md","filePath":"py-agent/architecture/domain-agent-architectures/research-agent.md","lastUpdated":1786083160000}'),t={name:"py-agent/architecture/domain-agent-architectures/research-agent.md"};function i(l,a,p,o,c,h){return n(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="研究型-agent" tabindex="-1">研究型 Agent <a class="header-anchor" href="#研究型-agent" aria-label="Permalink to &quot;研究型 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>研究型 Agent 将开放问题转为检索计划，查找和评估来源，保存可追踪证据，再综合成带引用的结论。它不同于普通 RAG：语料往往在任务执行时才发现，查询和范围会根据证据迭代，来源质量与时间边界是核心状态。</p><p>固定语料的加载、检索和引用链见<a href="/py-agent/knowledge/rag-foundations-data/rag-principles-boundaries">RAG 原理与边界</a>；需要操作动态网页时，可把<a href="/py-agent/architecture/domain-agent-architectures/browser-agent">浏览器 Agent</a>作为受限来源获取工具。本章关注研究任务本身的证据与停止模型。</p><h2 id="_1-研究任务边界" tabindex="-1">1. 研究任务边界 <a class="header-anchor" href="#_1-研究任务边界" aria-label="Permalink to &quot;1. 研究任务边界&quot;">​</a></h2><h3 id="_1-1-事实查证" tabindex="-1">1.1 事实查证 <a class="header-anchor" href="#_1-1-事实查证" aria-label="Permalink to &quot;1.1 事实查证&quot;">​</a></h3><p>回答一个可验证事实，重点是权威来源与时间。步骤较短，不必启用复杂多 Agent。</p><h3 id="_1-2-比较与综述" tabindex="-1">1.2 比较与综述 <a class="header-anchor" href="#_1-2-比较与综述" aria-label="Permalink to &quot;1.2 比较与综述&quot;">​</a></h3><p>定义标准，搜集多个候选与证据，处理冲突和覆盖缺口。需要结构化证据表。</p><h3 id="_1-3-调查与报告" tabindex="-1">1.3 调查与报告 <a class="header-anchor" href="#_1-3-调查与报告" aria-label="Permalink to &quot;1.3 调查与报告&quot;">​</a></h3><p>问题开放、来源多样、可能跨多个阶段和长时间运行。需要计划、Checkpoint、预算、人工校准和可审查产物。</p><h3 id="_1-4-边界" tabindex="-1">1.4 边界 <a class="header-anchor" href="#_1-4-边界" aria-label="Permalink to &quot;1.4 边界&quot;">​</a></h3><p>研究型 Agent 提供证据综合，不自动成为法律、医疗或投资专业意见。需专业责任的结论进入合格人工复核。</p><h2 id="_2-参考架构" tabindex="-1">2. 参考架构 <a class="header-anchor" href="#_2-参考架构" aria-label="Permalink to &quot;2. 参考架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research Brief</span></span>
<span class="line"><span>  -&gt; Planner</span></span>
<span class="line"><span>  -&gt; Query Queue</span></span>
<span class="line"><span>  -&gt; Search / Browser / Database Tools</span></span>
<span class="line"><span>  -&gt; Source Normalizer</span></span>
<span class="line"><span>  -&gt; Evidence Store + Claim Graph</span></span>
<span class="line"><span>  -&gt; Gap / Conflict Analyzer</span></span>
<span class="line"><span>  -&gt; Synthesizer</span></span>
<span class="line"><span>  -&gt; Citation Verifier</span></span>
<span class="line"><span>  -&gt; Human Review / Report</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>较大原文和附件进入 Artifact Store；Agent State 保存查询、来源 ID、Claim、缺口、预算和阶段，不把全部网页反复塞进消息。</p><h2 id="_3-research-brief" tabindex="-1">3. Research Brief <a class="header-anchor" href="#_3-research-brief" aria-label="Permalink to &quot;3. Research Brief&quot;">​</a></h2><h3 id="_3-1-问题" tabindex="-1">3.1 问题 <a class="header-anchor" href="#_3-1-问题" aria-label="Permalink to &quot;3.1 问题&quot;">​</a></h3><p>写成可调查问题，定义用户要做的决定。宽泛“研究 AI”需要先收窄对象、时间、地域和比较维度。</p><h3 id="_3-2-范围" tabindex="-1">3.2 范围 <a class="header-anchor" href="#_3-2-范围" aria-label="Permalink to &quot;3.2 范围&quot;">​</a></h3><p>包含/排除主题、截止日期、语言、来源类型、深度、格式和预算。时间敏感任务记录 <code>as_of</code>，避免把不同日期数据混为当前事实。</p><h3 id="_3-3-质量标准" tabindex="-1">3.3 质量标准 <a class="header-anchor" href="#_3-3-质量标准" aria-label="Permalink to &quot;3.3 质量标准&quot;">​</a></h3><p>定义权威性、新鲜度、多样性、引用完整性和最少交叉来源。高风险断言可要求两个独立来源或一个一级权威来源。</p><h3 id="_3-4-交付物" tabindex="-1">3.4 交付物 <a class="header-anchor" href="#_3-4-交付物" aria-label="Permalink to &quot;3.4 交付物&quot;">​</a></h3><p>报告结构、结论、证据表、争议、不确定性、方法和引用格式。交付物契约决定研究状态需要保存什么。</p><h2 id="_4-计划与问题分解" tabindex="-1">4. 计划与问题分解 <a class="header-anchor" href="#_4-计划与问题分解" aria-label="Permalink to &quot;4. 计划与问题分解&quot;">​</a></h2><h3 id="_4-1-子问题" tabindex="-1">4.1 子问题 <a class="header-anchor" href="#_4-1-子问题" aria-label="Permalink to &quot;4.1 子问题&quot;">​</a></h3><p>按因果、时间、参与者、候选或评估维度拆分，每个子问题有完成条件。不要仅把主问题换几种措辞搜索。</p><h3 id="_4-2-查询组合" tabindex="-1">4.2 查询组合 <a class="header-anchor" href="#_4-2-查询组合" aria-label="Permalink to &quot;4.2 查询组合&quot;">​</a></h3><p>建立广泛发现查询、精确验证查询、反例查询和来源限定查询。记录查询与它要解决的子问题。</p><h3 id="_4-3-动态更新" tabindex="-1">4.3 动态更新 <a class="header-anchor" href="#_4-3-动态更新" aria-label="Permalink to &quot;4.3 动态更新&quot;">​</a></h3><p>新证据可新增或合并子问题，但计划变更记录原因。防止研究无限扩张到与用户决定无关的主题。</p><h3 id="_4-4-并行" tabindex="-1">4.4 并行 <a class="header-anchor" href="#_4-4-并行" aria-label="Permalink to &quot;4.4 并行&quot;">​</a></h3><p>独立子问题可并行，最终通过共同 Claim/Evidence Schema 汇总。并行搜索相同内容只增加重复和成本。</p><h2 id="_5-来源发现" tabindex="-1">5. 来源发现 <a class="header-anchor" href="#_5-来源发现" aria-label="Permalink to &quot;5. 来源发现&quot;">​</a></h2><h3 id="_5-1-来源层级" tabindex="-1">5.1 来源层级 <a class="header-anchor" href="#_5-1-来源层级" aria-label="Permalink to &quot;5.1 来源层级&quot;">​</a></h3><p>优先一级来源：规范、官方文档、论文、原始数据、公司公告和法律文本；二级来源用于解释和发现线索；聚合摘要不能替代其引用的原文。</p><h3 id="_5-2-搜索结果" tabindex="-1">5.2 搜索结果 <a class="header-anchor" href="#_5-2-搜索结果" aria-label="Permalink to &quot;5.2 搜索结果&quot;">​</a></h3><p>搜索摘要可能截断、过时或与页面不一致，只用于选择候选。关键事实打开原文并定位支持片段。</p><h3 id="_5-3-可访问性" tabindex="-1">5.3 可访问性 <a class="header-anchor" href="#_5-3-可访问性" aria-label="Permalink to &quot;5.3 可访问性&quot;">​</a></h3><p>付费墙、登录、robots、许可和地域限制需要遵守。无法访问原文时明确标记二手引用，不伪装已核验。</p><h3 id="_5-4-内容不可信" tabindex="-1">5.4 内容不可信 <a class="header-anchor" href="#_5-4-内容不可信" aria-label="Permalink to &quot;5.4 内容不可信&quot;">​</a></h3><p>网页和文档可能含间接 Prompt Injection。它们只能成为证据数据，不能改变工具权限、研究范围或输出政策。</p><h2 id="_6-来源规范化" tabindex="-1">6. 来源规范化 <a class="header-anchor" href="#_6-来源规范化" aria-label="Permalink to &quot;6. 来源规范化&quot;">​</a></h2><p>每个来源保存：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source_id, canonical_url, title, author/organization</span></span>
<span class="line"><span>published_at, retrieved_at, version</span></span>
<span class="line"><span>content_hash, language, source_type</span></span>
<span class="line"><span>access/license notes, trust tier</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>处理重定向、Canonical URL、镜像和同文转载，避免把同一来源误算为多个独立证据。动态页面保存检索时间和必要快照/片段引用。</p><h2 id="_7-evidence-与-claim" tabindex="-1">7. Evidence 与 Claim <a class="header-anchor" href="#_7-evidence-与-claim" aria-label="Permalink to &quot;7. Evidence 与 Claim&quot;">​</a></h2><h3 id="_7-1-evidence" tabindex="-1">7.1 Evidence <a class="header-anchor" href="#_7-1-evidence" aria-label="Permalink to &quot;7.1 Evidence&quot;">​</a></h3><p>Evidence 是来源中的精确片段或数据，带位置、上下文和来源 ID。摘要不是 Evidence 本身。</p><h3 id="_7-2-claim" tabindex="-1">7.2 Claim <a class="header-anchor" href="#_7-2-claim" aria-label="Permalink to &quot;7.2 Claim&quot;">​</a></h3><p>Claim 是报告要表达的可验证陈述，记录支持、反驳或不确定证据。一个段落可有多个 Claim，每个需对应来源。</p><h3 id="_7-3-证据图" tabindex="-1">7.3 证据图 <a class="header-anchor" href="#_7-3-证据图" aria-label="Permalink to &quot;7.3 证据图&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claim C1</span></span>
<span class="line"><span>  &lt;- supports E1 (primary source)</span></span>
<span class="line"><span>  &lt;- supports E2 (independent dataset)</span></span>
<span class="line"><span>  &lt;- contradicts E3 (later date)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>图让冲突和缺口显式化；不是简单“收集 URL”。</p><h3 id="_7-4-笔记" tabindex="-1">7.4 笔记 <a class="header-anchor" href="#_7-4-笔记" aria-label="Permalink to &quot;7.4 笔记&quot;">​</a></h3><p>区分原文引述、Agent 摘要、推断和开放问题。每条笔记绑定来源，防止后续综合时把模型推断当原文事实。</p><h2 id="_8-来源评价与冲突" tabindex="-1">8. 来源评价与冲突 <a class="header-anchor" href="#_8-来源评价与冲突" aria-label="Permalink to &quot;8. 来源评价与冲突&quot;">​</a></h2><p>评价权威性、独立性、方法透明度、日期、直接性和利益关系。域名看似权威不代表当前页面支持特定断言。</p><p>冲突时先比较定义、时间、样本和方法，不通过投票决定真相。报告保留无法解决的分歧，并说明哪种条件下采用哪个结论。</p><h2 id="_9-综合与引用" tabindex="-1">9. 综合与引用 <a class="header-anchor" href="#_9-综合与引用" aria-label="Permalink to &quot;9. 综合与引用&quot;">​</a></h2><h3 id="_9-1-从-claim-写作" tabindex="-1">9.1 从 Claim 写作 <a class="header-anchor" href="#_9-1-从-claim-写作" aria-label="Permalink to &quot;9.1 从 Claim 写作&quot;">​</a></h3><p>先生成 Claim 大纲，再为每个 Claim 绑定 Evidence，最后展开文字。若关键 Claim 无证据，回到检索或降低结论强度。</p><h3 id="_9-2-引用准确性" tabindex="-1">9.2 引用准确性 <a class="header-anchor" href="#_9-2-引用准确性" aria-label="Permalink to &quot;9.2 引用准确性&quot;">​</a></h3><p>引用必须直接支持紧邻陈述；页面只提到主题不算支持。引用链接到可定位原文，保留标题、日期和访问时间。</p><h3 id="_9-3-引用完整性" tabindex="-1">9.3 引用完整性 <a class="header-anchor" href="#_9-3-引用完整性" aria-label="Permalink to &quot;9.3 引用完整性&quot;">​</a></h3><p>事实、数字、时间敏感和争议陈述需要引用；分析性过渡可不逐句引用。一个段落尾部的单一引用不自动支持全部句子。</p><h3 id="_9-4-不确定性" tabindex="-1">9.4 不确定性 <a class="header-anchor" href="#_9-4-不确定性" aria-label="Permalink to &quot;9.4 不确定性&quot;">​</a></h3><p>明确样本限制、时间边界、不可访问来源和推断，不用“可能”模糊所有结论，也不虚构精确置信度。</p><h2 id="_10-迭代与停止" tabindex="-1">10. 迭代与停止 <a class="header-anchor" href="#_10-迭代与停止" aria-label="Permalink to &quot;10. 迭代与停止&quot;">​</a></h2><p>Gap Analyzer 检查未回答子问题、无证据 Claim、单一来源、冲突和过期数据。只有缺口对用户决定重要时继续检索。</p><p>停止条件：关键问题达到证据门槛、连续查询没有新增高价值证据、预算/Deadline、来源不可达或需要人工缩小范围。更多网页不必然提高质量。</p><h2 id="_11-安全、隐私与版权" tabindex="-1">11. 安全、隐私与版权 <a class="header-anchor" href="#_11-安全、隐私与版权" aria-label="Permalink to &quot;11. 安全、隐私与版权&quot;">​</a></h2><p>限制域名和下载，隔离浏览器/文件，防 SSRF、恶意文件和资源耗尽。研究输入、来源和报告可能含个人数据，按用途最小化和保留。</p><p>遵守访问条款和许可，合理引用而非大段复制；不要把能访问等同于可训练、再分发。敏感调查控制来源和草稿访问。</p><h2 id="_12-评测" tabindex="-1">12. 评测 <a class="header-anchor" href="#_12-评测" aria-label="Permalink to &quot;12. 评测&quot;">​</a></h2><p>指标覆盖问题覆盖率、来源质量/多样性、新鲜度、Claim 正确性、引用准确/完整、冲突处理、时间、成本和安全。评测者抽查引用原文，不只让 Judge 阅读报告。</p><p>使用带已知证据的封闭任务验证机制，再用开放任务做专家评审。记录查询、来源、Evidence、Claim 和最终文本的完整 Lineage。</p><h2 id="_13-贯穿案例-比较两个模型服务方案" tabindex="-1">13. 贯穿案例：比较两个模型服务方案 <a class="header-anchor" href="#_13-贯穿案例-比较两个模型服务方案" aria-label="Permalink to &quot;13. 贯穿案例：比较两个模型服务方案&quot;">​</a></h2><p>以下使用虚构厂商演示结果流。任务是：“截至 2026-08-01，比较 Atlas AI 与 Boreal AI 是否满足境内客服数据处理要求，并给出试点建议。”</p><h3 id="_13-1-research-brief" tabindex="-1">13.1 Research Brief <a class="header-anchor" href="#_13-1-research-brief" aria-label="Permalink to &quot;13.1 Research Brief&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>决定：是否允许两家服务进入技术试点</span></span>
<span class="line"><span>包含：数据地域、保留、训练使用、工具调用、可用性</span></span>
<span class="line"><span>排除：最终采购价格谈判和法律意见</span></span>
<span class="line"><span>来源门槛：条款必须来自当前官方文档；内部要求来自批准版本</span></span>
<span class="line"><span>交付物：逐项结论、冲突、缺口和来源定位</span></span>
<span class="line"><span>停止条件：所有硬约束均有一级来源，或明确标为无法证明</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_13-2-来源与证据" tabindex="-1">13.2 来源与证据 <a class="header-anchor" href="#_13-2-来源与证据" aria-label="Permalink to &quot;13.2 来源与证据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>检索信息</th><th>Evidence</th></tr></thead><tbody><tr><td><code>S1</code> Atlas 数据处理条款 v4</td><td>2026-07-30 获取，官方 PDF 第 6 页</td><td>企业配置可关闭内容保留，但需账户审批</td></tr><tr><td><code>S2</code> Atlas 区域目录</td><td>2026-07-30 获取，官方页面“Asia”表格</td><td>指定模型在境内部署状态标为 Preview</td></tr><tr><td><code>S3</code> Boreal 隐私说明 v7</td><td>2026-07-31 获取，官方页面第 3 节</td><td>API 内容默认不用于训练，日志保留 7 天</td></tr><tr><td><code>S4</code> 内部数据要求 <code>POL-22</code></td><td>2026-07-15 批准，第 4.2 条</td><td>客服原文不得出境，生产日志保留不超过 24 小时</td></tr></tbody></table><p><code>S1</code> 与 <code>S2</code> 属于同一厂商，不能被算作两个独立来源；<code>S4</code> 是本次决策的内部权威标准，而不是外部事实来源。</p><h3 id="_13-3-claim-与缺口" tabindex="-1">13.3 Claim 与缺口 <a class="header-anchor" href="#_13-3-claim-与缺口" aria-label="Permalink to &quot;13.3 Claim 与缺口&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C1：Atlas 当前不能直接进入生产试点。</span></span>
<span class="line"><span>  supports E2：所需境内部署仍为 Preview</span></span>
<span class="line"><span>  supports E4：内部政策只允许已批准生产服务</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C2：Boreal 的默认日志策略不满足要求。</span></span>
<span class="line"><span>  supports E3：默认保留 7 天</span></span>
<span class="line"><span>  supports E4：上限为 24 小时</span></span>
<span class="line"><span>  gap：尚未找到可将日志缩短到 24 小时的正式配置证据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C3：两家都可进入“补证据”阶段，但均未达到生产准入。</span></span>
<span class="line"><span>  derived from C1 + C2；不是来源原文</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="_13-4-输出与停止" tabindex="-1">13.4 输出与停止 <a class="header-anchor" href="#_13-4-输出与停止" aria-label="Permalink to &quot;13.4 输出与停止&quot;">​</a></h3><p>最终报告不会写成“Boreal 更合规”，而是分别说明：Atlas 被服务成熟度阻塞，Boreal 被日志保留证据阻塞；下一步由采购与安全团队向两家索取正式承诺。在所有硬约束都有证据前，Agent 停止扩大搜索并将决定标记为“证据不足”，而不是根据营销页面推测。</p><p>这个案例展示了完整链路：问题决定来源门槛，来源产生可定位 Evidence，Evidence 支持或反驳 Claim，缺口决定继续检索还是转人工，最终文字只表达证据允许的强度。</p><h2 id="_14-常见误区" tabindex="-1">14. 常见误区 <a class="header-anchor" href="#_14-常见误区" aria-label="Permalink to &quot;14. 常见误区&quot;">​</a></h2><ol><li><strong>搜索结果摘要就是证据</strong>：可能截断或不准确。</li><li><strong>URL 数量等于研究深度</strong>：重复转载不独立。</li><li><strong>先写答案再找引用</strong>：容易选择性寻找支持。</li><li><strong>多个 Agent 搜索就更全面</strong>：可能重复且难合并。</li><li><strong>引用存在就忠实</strong>：来源未必支持具体 Claim。</li></ol><p>研究型 Agent 的核心数据结构是“问题—查询—来源—证据—Claim—结论”的可追踪链。自主搜索只有在这条链能被验证、冲突能被保留、范围能停止时才具有研究价值。</p>`,93)])])}const u=e(t,[["render",i]]);export{b as __pageData,u as default};
